def transform(grid):
    """Reorder each panel's variable column by its vertical number of zeros.

    The panel separators and all background cells are left untouched. The
    variable cells are at columns 1, 4, 7, 10, and 13, across the six odd rows.
    """
    out = [row[:] for row in grid]
    active_rows = range(1, len(grid), 2)
    panel_cols = [3 * panel + 1 for panel in range(5)]
    source_cols = sorted(
        panel_cols,
        key=lambda col: -sum(grid[row][col] == 0 for row in active_rows),
    )
    for row in active_rows:
        for dest_col, source_col in zip(panel_cols, source_cols):
            out[row][dest_col] = grid[row][source_col]
    return out


